  static Label Label(string text,float size,FontStyle style=FontStyle.Regular){return new Label{Text=text,Dock=DockStyle.Fill,Font=new Font("Segoe UI",size,style),ForeColor=Theme.Text,BackColor=Color.Transparent};}
  static void Button(RoundedButton button,string text,bool primary){button.Text=text;button.Primary=primary;button.BackColor=Theme.Surface;button.ForeColor=Theme.Text;button.Dock=DockStyle.Fill;button.UseVisualStyleBackColor=false;button.Cursor=Cursors.Hand;}
  internal void SetRoot(string value){try{root=Paths.ValidateRoot(value);inventory=installer.Inspect(root);location.Text=root;for(int i=0;i<4;++i){var m=catalog.Modules[i];selected[i].Checked=inventory.Plugins.Any(x=>x.Module==m.Id)||inventory.LegacyHost&&inventory.LegacyEnabled[m.Id]||inventory.Plugins.Count==0&&!inventory.LegacyHost;var existing=inventory.Plugins.FirstOrDefault(x=>x.Module==m.Id&&x.Path.Equals("Plugins/"+m.FileName,StringComparison.OrdinalIgnoreCase));if(existing!=null&&existing.Version!="unknown"&&ReleaseRules.Numeric(existing.Version)>ReleaseRules.Numeric(targets[m.Id].Version)){selected[i].Checked=false;}}
    hint.Text=inventory.LegacyHost?"Older COT found. Keep all enabled modules selected for its one-time conversion.":"Mod Manager found. Close MMC and the game before changing files.";if(fixture==null)Locator.Remember(root);RefreshVersions();}
   catch(Exception e){root=null;hint.Text=e.Message;Note(e.Message);}Buttons();}
  void RefreshVersions(){if(inventory==null)return;for(int i=0;i<4;++i){var m=catalog.Modules[i];var current=inventory.Plugins.FirstOrDefault(x=>x.Module==m.Id&&x.Path.Equals("Plugins/"+m.FileName,StringComparison.OrdinalIgnoreCase));string target=targets[m.Id].Version;versions[i].Text=inventory.Status(m)+(current!=null&&current.Sha256==targets[m.Id].DllSha256?" · keeping this version":" → "+target);}}
  void Buttons(){bool valid=root!=null&&location.Text==root;foreach(var item in new Control[]{browse,apply,updates,backups,remove,location})item.Enabled=!busy;foreach(var choice in selected)choice.Enabled=!busy;apply.Enabled=!busy&&valid&&selected.Any(x=>x.Checked);backups.Enabled=remove.Enabled=!busy&&valid;close.Enabled=!busy||!committing;close.Text=busy?"Cancel":"Close";}
  void Note(string message){if(InvokeRequired){BeginInvoke(new Action<string>(Note),message);return;}activity.Add(DateTime.Now.ToString("HH:mm:ss")+" "+message);if(activity.Count>1000)activity.RemoveAt(0);status.Text=message;}
  async Task Run(Func<Task> work){if(busy)return;busy=true;committing=false;cancellation=new CancellationTokenSource();progress.Visible=true;Buttons();try{await work();}catch(OperationCanceledException){Note("Cancelled. Existing installed files were not changed.");}catch(Exception e){string message=Paths.Explain(e);Note(message);ShowText("Operation stopped",message);}finally{busy=false;committing=false;cancellation.Dispose();progress.Visible=false;Buttons();}}
  Dictionary<string,string> Review(Plan plan){var unknown=installer.Review(plan);bool ask=unknown.Count>0||plan.Inventory.LegacyHost;if(ask){string text=plan.Inventory.LegacyHost?"The older COT host will be backed up. Its enabled modules will become independent plugins. Settings/history folders stay in place.\r\n\r\n":"";if(unknown.Count>0)text+="These plugin copies are not in the known-hash catalog. Back up and replace/remove these exact files?\r\n"+String.Join("\r\n",unknown.Select(x=>x.Path+"\r\nSHA-256: "+x.Sha256));if(MessageBox.Show(this,text,"Review migration",MessageBoxButtons.OKCancel,MessageBoxIcon.Information)!=DialogResult.OK)return null;}return unknown.ToDictionary(x=>x.Path,x=>x.Sha256);}
  async Task Install(){await Run(async()=>{
   string chosen=root;Paths.Closed(fixture,chosen);var wanted=new Dictionary<string,ModuleRelease>();for(int i=0;i<4;++i)if(selected[i].Checked)wanted.Add(catalog.Modules[i].Id,targets[catalog.Modules[i].Id]);
   var fresh=installer.Inspect(chosen);if(fresh.LegacyHost&&catalog.Modules.Any(m=>fresh.LegacyEnabled[m.Id]&&!wanted.ContainsKey(m.Id)))throw new IOException("Keep all enabled older-COT modules selected for migration, or explicitly remove unwanted ones first.");
   string cache=fixture!=null?Path.Combine(fixture.Parent,"Downloads"):Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"DynastyCOT","Downloads");
   var payloads=await Task.Run(()=>{var list=new List<PreparedModule>();foreach(var entry in wanted){var m=catalog.Get(entry.Key);if(fresh.Plugins.Any(x=>x.Path.Equals("Plugins/"+m.FileName,StringComparison.OrdinalIgnoreCase)&&x.Sha256==entry.Value.DllSha256))continue;list.Add(downloads.Prepare(m,entry.Value,cache,cancellation.Token,Note));}return list;});
   cancellation.Token.ThrowIfCancellationRequested();var older=new HashSet<string>(wanted.Where(x=>fresh.Plugins.Any(p=>p.Path.Equals("Plugins/"+catalog.Get(x.Key).FileName,StringComparison.OrdinalIgnoreCase)&&p.Version!="unknown"&&ReleaseRules.Numeric(p.Version)>ReleaseRules.Numeric(x.Value.Version))).Select(x=>x.Key));if(older.Count>0&&MessageBox.Show(this,"You selected older versions of "+String.Join(", ",older)+". Downgrade those plugins? Settings/history are kept.","Confirm older versions",MessageBoxButtons.OKCancel)!=DialogResult.OK){Note("Downgrade cancelled.");return;}var plan=installer.Install(chosen,wanted,payloads,older);Note(plan.Summary);var reviewed=Review(plan);if(reviewed==null){Note("Migration cancelled. No installed files changed.");return;}committing=true;Buttons();await Task.Run(()=>installer.Execute(plan,reviewed,Note));Note("Done. Open MMC and launch normally. Your backup is under Backups.");SetRoot(chosen);
  });}
  async Task Updates(){await Run(async()=>{
   var choices=await Task.Run(()=>{var all=new Dictionary<string,List<ModuleRelease>>();foreach(var module in catalog.Modules){Note("Checking "+module.Title+" releases (no downloads)...");try{all[module.Id]=downloads.Check(module,cancellation.Token);}catch(IOException e){Note(e.Message);all[module.Id]=new List<ModuleRelease>();}}return all;});
   using(var dialog=new Form{Text="Choose module versions",ClientSize=new Size(880,560),StartPosition=FormStartPosition.CenterParent,Icon=Icon,BackColor=Theme.Background,ForeColor=Theme.Text,Font=Font,MinimizeBox=false,MaximizeBox=false}){
    var list=new ListBox{Dock=DockStyle.Left,Width=190,BackColor=Theme.Surface,ForeColor=Theme.Text,BorderStyle=BorderStyle.None};list.Items.AddRange(catalog.Modules.Select(x=>x.Title).ToArray());dialog.Controls.Add(list);var right=new Panel{Dock=DockStyle.Fill,Padding=new Padding(14)};dialog.Controls.Add(right);right.BringToFront();var versionsBox=new ComboBox{Dock=DockStyle.Top,DropDownStyle=ComboBoxStyle.DropDownList};var notes=new TextBox{Dock=DockStyle.Fill,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,BackColor=Theme.Surface,ForeColor=Theme.Text,BorderStyle=BorderStyle.None};var actions=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=46,FlowDirection=FlowDirection.RightToLeft,WrapContents=false};var use=new RoundedButton{Text="Use this version",Primary=true,Width=220,Height=36,ForeColor=Theme.Text,BackColor=Theme.Surface};var done=new RoundedButton{Text="Done",Width=100,Height=36,ForeColor=Theme.Text,BackColor=Theme.Surface};done.Click+=(s,e)=>dialog.Close();actions.Controls.Add(done);actions.Controls.Add(use);right.Controls.Add(notes);right.Controls.Add(versionsBox);right.Controls.Add(actions);
    Action changed=()=>{var release=versionsBox.SelectedItem as ModuleRelease;notes.Text=DisplayText.Notes(release==null?"No verified standalone release was found. Keep your current version or try again later.":release.Version+"\r\n\r\n"+release.Compatibility+"\r\n\r\n"+release.Notes);use.Enabled=release!=null;};versionsBox.SelectedIndexChanged+=(s,e)=>changed();list.SelectedIndexChanged+=(s,e)=>{versionsBox.Items.Clear();versionsBox.Items.AddRange(choices[catalog.Modules[list.SelectedIndex].Id].Cast<object>().ToArray());if(versionsBox.Items.Count>0){int stable=choices[catalog.Modules[list.SelectedIndex].Id].FindIndex(x=>!x.Prerelease);versionsBox.SelectedIndex=stable<0?0:stable;}changed();};use.Click+=(s,e)=>{var m=catalog.Modules[list.SelectedIndex];targets[m.Id]=(ModuleRelease)versionsBox.SelectedItem;selected[list.SelectedIndex].Checked=true;RefreshVersions();Note(m.Title+" "+targets[m.Id].Version+" selected. Install / Update is still required.");use.Text="Version selected";};list.SelectedIndex=0;dialog.ShowDialog(this);
   }Note("Update check finished. Nothing was installed.");
  });}
  async Task Remove(bool all){if(root==null)return;var ids=catalog.Modules.Where((m,i)=>all||selected[i].Checked).Select(x=>x.Id).ToArray();if(ids.Length==0)return;if(MessageBox.Show(this,"Remove "+String.Join(", ",ids.Select(x=>catalog.Get(x).Title))+"? Settings and histories are kept. A backup will be made.","Remove modules",MessageBoxButtons.OKCancel)!=DialogResult.OK)return;await Run(async()=>{var plan=installer.Remove(root,ids);var reviewed=Review(plan);if(reviewed==null)return;committing=true;Buttons();await Task.Run(()=>installer.Execute(plan,reviewed,Note));SetRoot(root);Note("Selected plugins removed. Settings and history were kept.");});}
  async Task Backups(){if(root==null)return;var available=installer.Backups(root);if(available.Count==0){Note("No collection backups yet. Older COT backups remain in their original folder.");return;}Backup chosen=null;using(var dialog=new Form{Text="Restore a backup",ClientSize=new Size(680,290),StartPosition=FormStartPosition.CenterParent,Icon=Icon,BackColor=Theme.Background,ForeColor=Theme.Text,Font=Font}){var list=new ListBox{Dock=DockStyle.Fill,BackColor=Theme.Surface,ForeColor=Theme.Text};list.Items.AddRange(available.Cast<object>().ToArray());list.SelectedIndex=0;dialog.Controls.Add(list);var button=new Button{Text="Restore selected backup",Dock=DockStyle.Bottom,Height=42};dialog.Controls.Add(button);button.Click+=(s,e)=>{chosen=(Backup)list.SelectedItem;dialog.Close();};dialog.ShowDialog(this);}if(chosen==null||MessageBox.Show(this,"Restore the plugin versions in this backup? Settings/history are kept. Restore newer backups first.","Restore backup",MessageBoxButtons.OKCancel)!=DialogResult.OK)return;await Run(async()=>{committing=true;Buttons();await Task.Run(()=>installer.Restore(root,chosen.Directory));SetRoot(root);Note("Backup restored. Restart MMC and the game.");});}
  void ShowText(string title,string text){using(var dialog=new Form{Text=title,ClientSize=new Size(800,480),StartPosition=FormStartPosition.CenterParent,Icon=Icon,BackColor=Theme.Background}){var box=new TextBox{Text=DisplayText.Notes(text),Dock=DockStyle.Fill,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Both,Font=new Font("Consolas",9),BackColor=Theme.Surface,ForeColor=Theme.Text};dialog.Controls.Add(box);dialog.ShowDialog(this);}}
  internal void AuditLayout(){PerformLayout();foreach(Control control in new[]{apply,close,details,remove,backups,updates}){if(!control.Visible||control.Parent.RectangleToScreen(control.Parent.ClientRectangle).Contains(control.RectangleToScreen(control.ClientRectangle))==false)throw new IOException("Footer action is clipped: "+control.Text);var measured=TextRenderer.MeasureText(control.Text,control.Font);if(measured.Width>control.Width||measured.Height>control.Height)throw new IOException("Footer label is clipped: "+control.Text);}foreach(var label in descriptions){var size=TextRenderer.MeasureText(label.Text,label.Font,new Size(label.Width-label.Padding.Horizontal,Int32.MaxValue),TextFormatFlags.WordBreak|TextFormatFlags.TextBoxControl);if(size.Height>label.Height-label.Padding.Vertical)throw new IOException("Module description is clipped: "+label.Text);}}
 }
 internal static class Locator {
  static string Preference{get{return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"DynastyCOT","last-manager.txt");}}
  internal static void Remember(string root){try{Directory.CreateDirectory(Path.GetDirectoryName(Preference));File.WriteAllText(Preference,root);}catch(IOException){}catch(UnauthorizedAccessException){}}
  internal static string Find(){try{if(File.Exists(Preference))return Paths.ValidateRoot(File.ReadAllText(Preference));}catch(IOException){}catch(ArgumentException){}
   foreach(var process in Process.GetProcessesByName("MMCModManager"))using(process)try{return Paths.ValidateRoot(Path.GetDirectoryName(process.MainModule.FileName));}catch(System.ComponentModel.Win32Exception){}catch(InvalidOperationException){}catch(IOException){}
   var starts=new List<string>{AppDomain.CurrentDomain.BaseDirectory,Environment.CurrentDirectory,Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),"Downloads"),Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory)};
   foreach(var drive in DriveInfo.GetDrives())if(drive.DriveType==DriveType.Fixed)foreach(string part in new[]{@"Apps\CFB 27\MMC",@"Games\CFB 27\MMC",@"MMC",@"Tools\MMC"})starts.Add(Path.Combine(drive.Name,part));
   var found=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(string start in starts)for(var directory=new DirectoryInfo(start);directory!=null;directory=directory.Parent)try{var valid=Paths.ValidateRoot(directory.FullName);found.Add(valid);break;}catch(IOException){}catch(UnauthorizedAccessException){}return found.Count==1?found.First():null;
  }
 }
